[tool error]
{
  "ok": false,
  "name": "offset_entity",
  "error": {
    "type": "invalid_params",
    "message": "Additional properties are not allowed ('space' was unexpected)",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "ids": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 1,
          "description": "what to copy parallel: one line, polyline, arc or circle, or several that join end to end (in order along them), offset together as one path. Reference elements ('BASE:LN-017') may be copied into this document"
        },
        "distance": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "how far, with side or toward"
        },
        "side": {
          "type": "string",
          "enum": [
            "left",
            "right"
          ],
          "description": "left or right of the direction the path runs: a line start to end, a polyline in vertex order, an arc or circle counter-clockwise, a chain in the order of ids"
        },
        "toward": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "a point on the side to offset to, the way a drafter clicks the side"
        },
        "through": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "a point the parallel passes through; the distance is measured square to the path"
        },
        "offsets": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": [
              "number",
              "string"
            ]
          },
          "description": "several parallels at once, right of the path's direction positive ('15L', '15R' say the side): [-15, 15] is both edges of a 30 ft pavement"
        },
        "join": {
          "type": "string",
          "enum": [
            "sharp",
            "round"
          ],
          "description": "outside corners: sharp extends the pieces to meet (default), round swings an arc about the corner"
        },
        "connect_tolerance": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "largest gap between chained pieces (default 0.01)"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer of the copies; default the source's layer"
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        }
      },
      "required": [
        "ids"
      ],
      "additionalProperties": false
    },
    "example": {
      "ids": [
        "LN-001"
      ],
      "distance": 15.0,
      "side": "right",
      "layer": "V-ROAD-EOP"
    }
  },
  "warnings": []
}
